    /// The registry name without its namespace; `None` for `Unknown`.
    pub fn name(self) -> Option<&'static str> {
        if let Self::Unknown(_) = self {
            return None;
        }
        usize::try_from(self.id())
            .ok()
            .and_then(|i| ENTITY_NAMES.get(i))
            .copied()
    }

    /// The kind a registry name (without namespace) names.
    pub fn from_name(name: &str) -> Option<Self> {
        ENTITY_BY_NAME
            .binary_search_by(|(n, _)| (*n).cmp(name))
            .ok()
            .and_then(|i| ENTITY_BY_NAME.get(i))
            .map(|(_, k)| *k)
    }
